const subject = $json.subject || '';
const textPlain = $json.textPlain || '';  // from your IMAP output
const from = $json.from || '';
const to = $json.to || '';
const date = $json.date || '';

function stripQuoted(text) {
  const markers = [
    '\nOn ',                    // "On Mon, Jan 1, 2025 at..."
    '\nFrom:', 
    '\n> ',                     // quoted lines
    '-----Original Message-----'
  ];
  let cleaned = text;
  for (const m of markers) {
    const idx = cleaned.indexOf(m);
    if (idx !== -1) {
      cleaned = cleaned.slice(0, idx);
      break;
    }
  }
  return cleaned.trim();
}

const bodyClean = stripQuoted(textPlain);

return {
  subject,
  from,
  to,
  date,
  body: bodyClean,
};

// -------- 1) Get raw text from the AI node --------

// Adjust these paths if your AI Agent outputs the text somewhere else.
const raw =
  ($json.output) ||                                  // AI Agent 'output' field
  ($json.message && $json.message.content) ||        // OpenAI-style
  ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) ||
  '';

const cleaned = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let triage;

try {
  triage = JSON.parse(cleaned);
} catch (e) {
  // Fallback object if JSON.parse fails
  triage = {
    category: 'other',
    urgency: 3,
    confidence: 0.0,
    summary: 'Failed to parse JSON from LLM.',
    action_items: [],
    suggested_reply: '',
    metadata: {},
    _raw: cleaned,
    _error: e.message,
  };
}

// -------- 2) Normalise metadata fields --------

if (!triage.metadata) {
  triage.metadata = {};
}

// Turn null/undefined meeting_location into empty string
triage.metadata.meeting_location = triage.metadata.meeting_location ?? '';

// Turn null/undefined meeting_datetime into empty string
triage.metadata.meeting_datetime = triage.metadata.meeting_datetime ?? '';

// Optional: normalise related_project too
triage.metadata.related_project = triage.metadata.related_project ?? '';

// Optional: ensure suggested_reply is always a string
triage.suggested_reply = triage.suggested_reply ?? '';


// -------- 3) Carry original email metadata from Clean Email node --------
// NOTE: change "Code in JavaScript" below if your clean-body node has a different name.

const cleanNode = $item(0).$node["Code in JavaScript"].json;

triage._subject = cleanNode.subject;
triage._from = cleanNode.from;
triage._to = cleanNode.to || '';

// -------- 4) Return the final triage object --------

return triage;
